import Image from "next/image";

const paths = [
  {
    eyebrow: "Path One",
    title: "Life, Stories\n& Growth",
    image: "/images/paths/life-path.jpg",
    description:
      "For anyone navigating grief, motherhood, relationships, loss, identity, or simply trying to figure life out.",
    words: ["Stories", "Reflection", "Grief", "Growth", "Finding Home"],
    button: "Explore the Stories",
    href: "#stories",
    accent: "#234531",
  },
  {
    eyebrow: "Path Two",
    title: "The ODS’s\nHourglass\nof Clarity™",
    image: "/images/paths/ods-path.jpg",
    description:
      "For Oncology Data Specialists seeking practical tools, simplified learning, and confidence in an increasingly complex profession.",
    words: ["AJCC", "SEER", "STORE", "AI", "EHR"],
    button: "Enter the Hourglass",
    href: "#ods-hourglass",
    accent: "#67204D",
  },
];

export default function ChooseYourPath() {
  return (
    <section
      id="choose-your-path"
      className="bg-[#F7F2E9] px-6 py-14 lg:px-8 lg:py-16"
    >
      <div className="mx-auto max-w-7xl">
        <div className="text-center">
          <p className="text-[10px] uppercase tracking-[0.4em] text-[#234531]">
            Where do you need clarity today?
          </p>

          <h2 className="mt-3 font-serif text-4xl text-[#5A2346] sm:text-5xl">
            Choose Your Path
          </h2>

          <div className="mx-auto my-5 flex items-center justify-center gap-3">
            <span className="h-px w-16 bg-[#C89D4A]" />
            <span className="h-2 w-2 rotate-45 bg-[#C89D4A]" />
            <span className="h-px w-16 bg-[#C89D4A]" />
          </div>

          <p className="mx-auto max-w-xl text-sm leading-6 text-[#63655F]">
            Life and work may look different, but both begin with the same
            decision: keep moving.
          </p>
        </div>

        <div className="mt-10 grid gap-8 lg:grid-cols-2">
          {paths.map((path) => (
            <article
              key={path.eyebrow}
              className="group overflow-hidden rounded-[1.75rem] border border-[#D8CCBA] bg-[#FFFDF8] shadow-[0_16px_40px_rgba(62,47,36,0.1)] transition duration-300 hover:-translate-y-1 hover:shadow-[0_24px_60px_rgba(62,47,36,0.16)]"
            >
              <div className="relative min-h-[310px] overflow-hidden">
                <Image
                  src={path.image}
                  alt=""
                  fill
                  sizes="(min-width: 1024px) 50vw, 100vw"
                  className="object-cover transition duration-700 group-hover:scale-[1.03]"
                />

                <div className="absolute inset-0 bg-gradient-to-t from-black/75 via-black/15 to-transparent" />

                <div className="absolute inset-x-0 bottom-0 p-7 text-white">
                  <p className="text-[10px] uppercase tracking-[0.38em]">
                    {path.eyebrow}
                  </p>

                  <h3 className="mt-3 whitespace-pre-line font-serif text-4xl leading-[1.02]">
                    {path.title}
                  </h3>
                </div>
              </div>

              <div className="p-7 sm:p-8">
                <p className="max-w-lg text-[15px] leading-7 text-[#3E403B]">
                  {path.description}
                </p>

                <div className="mt-6 flex flex-wrap gap-2">
                  {path.words.map((word) => (
                    <span
                      key={word}
                      className="rounded-full border border-[#DDD2C2] bg-[#F8F3EA] px-3 py-1.5 text-xs text-[#50544E]"
                    >
                      {word}
                    </span>
                  ))}
                </div>

                <a
                  href={path.href}
                  className="mt-7 inline-flex items-center gap-2 rounded-sm px-6 py-3 text-xs uppercase tracking-[0.14em] text-white transition hover:opacity-90"
                  style={{ backgroundColor: path.accent }}
                >
                  {path.button}
                  <span aria-hidden="true">→</span>
                </a>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}