import Image from "next/image";

export default function MeetJenn() {
  return (
    <section id="story" className="bg-[#FFFDF8] px-6 py-16 lg:px-8">
      <div className="mx-auto grid max-w-7xl items-center gap-12 lg:grid-cols-[0.8fr_1.2fr]">
        <div className="relative min-h-[430px] overflow-hidden rounded-t-[8rem] rounded-b-md border border-[#D8CCBA] shadow-[0_20px_45px_rgba(62,47,36,0.12)]">
          <Image
            src="/images/jenn-portrait.jpg"
            alt="Jenn Kassan"
            fill
            sizes="(min-width: 1024px) 40vw, 100vw"
            className="object-cover object-center"
          />
        </div>

        <div className="max-w-2xl">
          <p className="text-[10px] uppercase tracking-[0.4em] text-[#234531]">
            Hi, I&apos;m Jenn
          </p>

          <h2 className="mt-4 font-serif text-4xl leading-tight text-[#5A2346] sm:text-5xl">
            Not because I&apos;ve figured life out.
            <span className="mt-2 block text-[#234531]">
              Because I&apos;m still figuring it out.
            </span>
          </h2>

          <div className="my-6 flex items-center gap-3">
            <span className="h-px w-16 bg-[#C89D4A]" />
            <span className="h-2 w-2 rotate-45 bg-[#C89D4A]" />
          </div>

          <div className="space-y-4 text-[15px] leading-7 text-[#3E403B]">
            <p>
              I&apos;ve spent my career helping people make sense of complicated
              cancer registry information.
            </p>

            <p>
              I&apos;ve spent my life trying to make sense of grief, family,
              motherhood, love, change, and all the messy spaces in between.
            </p>

            <p className="font-serif text-xl italic text-[#5A2346]">
              It turns out the process is the same.
            </p>

            <p>
              Ask questions. Stay curious. Find enough clarity to take the next
              step.
            </p>
          </div>

          <a
            href="#about"
            className="mt-7 inline-flex items-center gap-2 text-sm font-semibold uppercase tracking-[0.14em] text-[#234531] transition hover:text-[#B77A24]"
          >
            More About My Story
            <span aria-hidden="true">→</span>
          </a>
        </div>
      </div>
    </section>
  );
}